___CSS_LOADER_EXPORT___.push([module.id, `.asset-hero {
  max-width: 1100px;
  margin: 0 auto;
  padding: 48px 20px;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 32px;
}

.eyebrow {
  text-transform: uppercase;
  font-weight: 700;
}

.headline {
  font-size: 1.25rem;
}

.facts {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin: 20px 0;
}

.facts span, .price-card {
  padding: 12px;
  border: 1px solid #ddd;
  border-radius: 10px;
}

.price-card strong {
  display: block;
  font-size: 2rem;
}

.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.actions a {
  padding: 12px 18px;
  border: 1px solid #aaa;
  border-radius: 8px;
  text-decoration: none;
}

.actions .primary {
  font-weight: 700;
}

.asset-sections {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px 40px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}

.asset-sections article {
  padding: 20px;
  border: 1px solid #ddd;
  border-radius: 10px;
}

.loading {
  padding: 40px;
}

@media (max-width: 760px) {
  .asset-hero {
    grid-template-columns: 1fr;
  }
